import java.util.*;

class Solution {
    public int[] reverseViaStack(int[] nums) {
        Deque<Integer> stack = new ArrayDeque<>();
        for (int x : nums) stack.push(x);
        int[] res = new int[nums.length];
        for (int i = 0; i < res.length; i++) {
            res[i] = stack.pop();
        }
        return res;
    }
}

