import java.util.*;

class Solution {
    public int[] throughQueue(int[] nums) {
        Queue<Integer> q = new ArrayDeque<>();
        for (int x : nums) q.offer(x);
        int[] res = new int[nums.length];
        for (int i = 0; i < res.length; i++) res[i] = q.poll();
        return res;
    }
}
